const Sqlite = require('sqlite3');
const path = require('path');

const dbPath = path.resolve(__dirname, '../../../../Data/Database.db');

const localDB = new Sqlite.Database(dbPath, (err) => {
  if (err) {
    console.log("DB path : ", dbPath);
    return console.log("error : ", err.message);
  }
  console.log("connected with Database");
});

//Migration Functions
const Migrations = [
  () => {
    //creating all table .
    for (let keys of Object.keys(createTables)) {
      console.log('creating table', keys);
      localDB.serialize(() => {
        localDB.run(createTables[keys], (err) => {
          if (err) console.log(keys, 'error: ', err);
        });
      });
    }
  },

  () => {

    //creating triggers
    for (let keys of Object.keys(triggers)) {
      console.log('creating triggers', keys);
      localDB.run(triggers[keys], (err) => {
        if (err) console.log(keys, 'error: ', err);
      });
    }
  },

  () => {
    //insering row data.

    for (let keys of Object.keys(insertData)) {

      console.log('inserting data to', keys);
      localDB.serialize(() => {
        localDB.run(insertData[keys], (err) => {
          if (err) console.log(keys, 'error: ', err);
        });
      });

    }
  }
];
let migrationLength = Migrations.length;


//start migrating
localDB.serialize(() => {
  let migrationCount;
  localDB.get(`PRAGMA user_version;`, (err, data) => {
    if (err) return console.log("ERROR!", err);
    console.log(data);
    migrationCount = data.user_version ? data.user_version : 0;
    // console.log("migra", migrationCount);
    // console.log("migra", Migrations.length);
    localDB.run(`PRAGMA foreign_keys = on`);

    if (Migrations.length > migrationCount) {
      console.log("statring");
      localDB.run(`BEGIN TRANSACTION;`);

      for (const migration of Migrations.splice(migrationCount)) {
        migration();
      }

      localDB.run(`PRAGMA user_version = ${migrationLength}`, (err) => {
        if (err) console.log("pragma error : ", err);
      });

      localDB.run(`COMMIT;`, (err) => {
        if (err) { }
        else {
          console.log("user version updated to ", migrationLength);
        }
      });
    }

  });
});


